// TicketProgressStep defines model for TicketProgressStep.
type TicketProgressStep string

// TicketReopen defines model for TicketReopen.
type TicketReopen struct {
	// CanReopen The viewer may reopen the ticket now.
	CanReopen bool `json:"canReopen"`

	// Until The ticket can be reopened until then, and closes after it.
	Until time.Time `json:"until"`
}

// TicketSla The targets for the current priority, from the project's SLA when the ticket was opened,
// and the live clocks (null until the SLA engine has run for the ticket, within a minute).
type TicketSla struct {
	// Calendar `business_hours` counts working minutes only; `always` runs 24/7.
	Calendar             SlaCalendar `json:"calendar"`
	FirstResponse        Duration    `json:"firstResponse"`
	FirstResponseClock   *SlaClock   `json:"firstResponseClock"`
	PauseOnUat           bool        `json:"pauseOnUat"`
	PauseOnWaitingClient bool        `json:"pauseOnWaitingClient"`
	Priority             Priority    `json:"priority"`

	// Resolution Resolve time for incidents, delivery time for service requests.
	Resolution      Duration  `json:"resolution"`
	ResolutionClock *SlaClock `json:"resolutionClock"`
}

// TicketStatus defines model for TicketStatus.
type TicketStatus string

// TicketStatusCause Why the status changed when it wasn't a plain move by hand: the system moved it
// (assignment, requester_reply, uat_auto_approved, auto_closed), the client answered
// (uat_approved, uat_rejected, reopened), an agent resolved with the Definition of Done
// unmet (dod_skipped, with the reason). `code_activity`, `code_done` and `code_reopened`
// appear in history only: GitHub/GitLab moved tickets until 17 Nov.
type TicketStatusCause string

// TicketStatusInput defines model for TicketStatusInput.
type TicketStatusInput struct {
	From *TicketStatus `json:"from,omitempty"`

	// Reason Needed to resolve a ticket whose mandatory Definition of Done isn't met; ignored otherwise.
	Reason *string      `json:"reason,omitempty"`
	Status TicketStatus `json:"status"`
}

// TicketSummary defines model for TicketSummary.
type TicketSummary struct {
	Assignee  *Ref               `json:"assignee"`
	Client    Ref                `json:"client"`
	CreatedAt time.Time          `json:"createdAt"`
	Id        openapi_types.UUID `json:"id"`

	// Key Example: HD-24871
	Key        string       `json:"key"`
	Priority   Priority     `json:"priority"`
	Requester  Ref          `json:"requester"`
	ResolvedAt *time.Time   `json:"resolvedAt"`
	Status     TicketStatus `json:"status"`

	// Subject Example: e-Office login fails for all staff
	Subject   string     `json:"subject"`
	Type      TicketType `json:"type"`
	UpdatedAt time.Time  `json:"updatedAt"`
}

// TicketType defines model for TicketType.
type TicketType string

// TicketUat defines model for TicketUat.
type TicketUat struct {
	// AutoApproveAt When the fix is approved without an answer; null when it waits however long it takes.
	AutoApproveAt *time.Time `json:"autoApproveAt"`

	// CanAnswer The viewer may approve or reject.
	CanAnswer bool `json:"canAnswer"`

	// Instructions The team's latest public reply, which says what to test.
	Instructions *string `json:"instructions"`
}

